import SwiftUI
import WebKit

/// Pocket GM — the menu and all three games (soccer, baseball, hockey) in one
/// full-screen WKWebView.
///
/// Web/ is generated by `node build.js --ios` in the repo root and ships inside
/// the app bundle, so everything runs with no network. The games keep their saves
/// in localStorage and IndexedDB under distinct keys, so sharing one web view's
/// storage is safe (see the key table in CLAUDE.md).
struct ContentView: View {
    private let background = Color(red: 0.043, green: 0.071, blue: 0.125) // #0b1220

    var body: some View {
        // The web view stays inside the safe area rather than relying on each game's
        // env(safe-area-inset-*) padding — baseball has none, so its header would
        // sit under the Dynamic Island.
        GameWebView()
            .background(background.ignoresSafeArea())
    }
}

struct GameWebView: UIViewRepresentable {
    func makeCoordinator() -> SaveBridge { SaveBridge() }

    func makeUIView(context: Context) -> WKWebView {
        let config = WKWebViewConfiguration()
        config.allowsInlineMediaPlayback = true
        // Persist every game's saves across launches.
        config.websiteDataStore = .default()
        config.userContentController.add(context.coordinator, name: "pgmSaves")

        let webView = WKWebView(frame: .zero, configuration: config)
        webView.isOpaque = false
        webView.backgroundColor = UIColor(red: 0.043, green: 0.071, blue: 0.125, alpha: 1)
        webView.scrollView.backgroundColor = webView.backgroundColor
        webView.scrollView.bounces = false
        webView.scrollView.contentInsetAdjustmentBehavior = .never
        // Swipe from the left edge to go back to the menu, alongside each game's ⌂ button.
        webView.allowsBackForwardNavigationGestures = true
        webView.scrollView.keyboardDismissMode = .onDrag

        webView.navigationDelegate = context.coordinator
        loadMenu(into: webView)
        return webView
    }

    func updateUIView(_ webView: WKWebView, context: Context) {}

    private func loadMenu(into webView: WKWebView) {
        guard let indexURL = Bundle.main.url(forResource: "index", withExtension: "html", subdirectory: "Web") else {
            let msg = """
            <body style="background:#0b1220;color:#e6edf7;font-family:-apple-system,sans-serif;padding:24px">
            <h2>Web/index.html is missing from the app bundle.</h2>
            <p>Run <code>node build.js --ios</code> in the repo root, then build again.</p>
            </body>
            """
            webView.loadHTMLString(msg, baseURL: nil)
            return
        }
        // Read access to all of Web/ so the menu can open each game's folder.
        webView.loadFileURL(indexURL, allowingReadAccessTo: indexURL.deletingLastPathComponent())
    }
}

/// Moves saves in and out of the app.
///
/// Out: the menu's "Back up all saves" posts the backup JSON here, and it goes to
/// the share sheet (Files, AirDrop…). A download link can't do that in a web view.
///
/// In: any backup dropped into Documents/Import — visible in the Files app as
/// On My iPhone › Pocket GM › Import — is merged in the next time the menu loads,
/// then moved to Documents/Imported. That's also how the old single-game apps'
/// exports come across. The menu's "Restore from a backup" does the same by hand.
final class SaveBridge: NSObject, WKScriptMessageHandler, WKNavigationDelegate {
    private let fm = FileManager.default
    private var documents: URL { fm.urls(for: .documentDirectory, in: .userDomainMask)[0] }

    override init() {
        super.init()
        // Create Import/ up front so it's there to drop files into from the Files app.
        try? fm.createDirectory(at: documents.appendingPathComponent("Import"), withIntermediateDirectories: true)
    }

    func userContentController(_ controller: WKUserContentController, didReceive message: WKScriptMessage) {
        guard let body = message.body as? [String: Any],
              let name = body["name"] as? String, let json = body["json"] as? String else { return }
        let url = fm.temporaryDirectory.appendingPathComponent(name)
        do { try json.write(to: url, atomically: true, encoding: .utf8) } catch { return }
        share(url, from: message.webView)
    }

    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        // Only the menu page carries the restore code.
        guard webView.url?.deletingLastPathComponent().lastPathComponent == "Web" else { return }
        let inbox = documents.appendingPathComponent("Import")
        let done = documents.appendingPathComponent("Imported")
        let files = ((try? fm.contentsOfDirectory(at: inbox, includingPropertiesForKeys: nil)) ?? [])
            .filter { $0.pathExtension.lowercased() == "json" }
            .sorted { $0.lastPathComponent < $1.lastPathComponent }
        guard !files.isEmpty else { return }
        try? fm.createDirectory(at: done, withIntermediateDirectories: true)
        Task { @MainActor in
            for file in files {
                guard let json = try? String(contentsOf: file, encoding: .utf8) else { continue }
                do {
                    _ = try await webView.callAsyncJavaScript("return await window.pgmRestore(json)", arguments: ["json": json], contentWorld: .page)
                    let dest = done.appendingPathComponent(file.lastPathComponent)
                    try? fm.removeItem(at: dest)
                    try? fm.moveItem(at: file, to: dest)
                } catch {
                    // Leave it in Import/ so it's retried; the menu shows the error.
                    print("Pocket GM: couldn't import \(file.lastPathComponent): \(error)")
                }
            }
        }
    }

    private func share(_ url: URL, from webView: WKWebView?) {
        guard let webView, let root = webView.window?.rootViewController else { return }
        let sheet = UIActivityViewController(activityItems: [url], applicationActivities: nil)
        sheet.popoverPresentationController?.sourceView = webView
        sheet.popoverPresentationController?.sourceRect = CGRect(x: webView.bounds.midX, y: webView.bounds.midY, width: 1, height: 1)
        (root.presentedViewController ?? root).present(sheet, animated: true)
    }
}
